import{_ as a,a as o,b as t,c as i,d as r}from"./chunks/qr_libre2direct_samsung_30.BlQvG7BZ.js";import{_ as n,o as s,c as l,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const q=JSON.parse('{"title":"Libre 2 Direct","description":"","frontmatter":{"source_hash":"09c4f80004","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/troubleshoot/libre2direct.md","filePath":"it/troubleshoot/libre2direct.md"}'),u={name:"it/troubleshoot/libre2direct.md"};function d(h,e,p,m,b,v){return s(),l("div",null,[...e[0]||(e[0]=[c('<h1 id="libre2-direct" tabindex="-1">Libre2 Direct <a class="header-anchor" href="#libre2-direct" aria-label="Permalink to &quot;Libre2 Direct {#libre2-direct}&quot;">​</a></h1><p>Libre2 (solo versione UE) può collegarsi direttamente a xDrip senza bridge. Questa pagina mostra come dovrebbe apparire un sistema funzionante.</p><p>Vedi qui per <a href="./../install/libre2.html#prerequisites">imparare a configurarlo...</a></p><h2 id="what-it-should-look-like" tabindex="-1">Come dovrebbe apparire <a class="header-anchor" href="#what-it-should-look-like" aria-label="Permalink to &quot;Come dovrebbe apparire {#what-it-should-look-like}&quot;">​</a></h2><p>Se la configurazione è corretta e un nuovo sensore è attivo, le pagine di stato e i log di xDrip dovrebbero apparire come mostrato qui sotto. Nota: per il funzionamento con Libre 2 direct non cambia nulla nella scheda Uploaders.</p><p>Vai in Stato del sistema di xDrip e anche nella pagina BT Device. Se non sai come fare, guarda prima <a href="./systemstatus.html">qui</a>.</p><h2 id="classic-status-page" tabindex="-1">Pagina di stato classica <a class="header-anchor" href="#classic-status-page" aria-label="Permalink to &quot;Pagina di stato classica {#classic-status-page}&quot;">​</a></h2><img src="'+a+'" style="zoom:40%;"><h3 id="version" tabindex="-1">Versione <a class="header-anchor" href="#version" aria-label="Permalink to &quot;Versione {#version}&quot;">​</a></h3><p>Cambia a seconda della tua versione di xDrip</p><h3 id="data-source" tabindex="-1">Sorgente dati <a class="header-anchor" href="#data-source" aria-label="Permalink to &quot;Sorgente dati {#data-source}&quot;">​</a></h3><p>Qui dovrebbe comparire LimiTTer. Anche se fuorviante, è il comportamento normale.</p><h3 id="bluetooth-device" tabindex="-1">Dispositivo Bluetooth <a class="header-anchor" href="#bluetooth-device" aria-label="Permalink to &quot;Dispositivo Bluetooth {#bluetooth-device}&quot;">​</a></h3><p>È l&#39;identificativo seriale univoco del sensore. Inizia con ABBOTT...</p><h3 id="connection-status" tabindex="-1">Stato della connessione <a class="header-anchor" href="#connection-status" aria-label="Permalink to &quot;Stato della connessione {#connection-status}&quot;">​</a></h3><p>Dovrebbe essere &quot;connesso&quot;.</p><h3 id="sensor-start" tabindex="-1">Sensore attivato <a class="header-anchor" href="#sensor-start" aria-label="Permalink to &quot;Sensore attivato {#sensor-start}&quot;">​</a></h3><p>L&#39;ora in cui è stato avviato il sensore.</p><h3 id="restart-collector-button" tabindex="-1">Pulsante Riavvia Collector <a class="header-anchor" href="#restart-collector-button" aria-label="Permalink to &quot;Pulsante Riavvia Collector {#restart-collector-button}&quot;">​</a></h3><p>Ferma la funzione di collector di xDrip e poi la riavvia da zero (compresa la connessione Bluetooth al dispositivo che era stata interrotta)</p><h3 id="forget-device-button" tabindex="-1">Pulsante Dimentica questo dispositivo <a class="header-anchor" href="#forget-device-button" aria-label="Permalink to &quot;Pulsante Dimentica questo dispositivo {#forget-device-button}&quot;">​</a></h3><p>Rimuove il dispositivo Bluetooth dai dispositivi conosciuti: devi fare una scansione Bluetooth per trovarlo e associarlo di nuovo, oppure rifare una scansione NFC.</p><h3 id="refresh-button" tabindex="-1">Pulsante Aggiorna <a class="header-anchor" href="#refresh-button" aria-label="Permalink to &quot;Pulsante Aggiorna {#refresh-button}&quot;">​</a></h3><p>Lo stato non è in tempo reale, a differenza della scheda BT Device; Aggiorna verifica lo stato della connessione. <br></p><h2 id="bt-device-page" tabindex="-1">Pagina BT Device <a class="header-anchor" href="#bt-device-page" aria-label="Permalink to &quot;Pagina BT Device {#bt-device-page}&quot;">​</a></h2><p>Scorri lo schermo verso sinistra per visualizzare la pagina BT Device.</p><img src="'+o+'" style="zoom:40%;"><h3 id="bluetooth-collector-status" tabindex="-1">Bluetooth Collector Status <a class="header-anchor" href="#bluetooth-collector-status" aria-label="Permalink to &quot;Bluetooth Collector Status {#bluetooth-collector-status}&quot;">​</a></h3><h3 id="phone-service-state" tabindex="-1">Phone Service State <a class="header-anchor" href="#phone-service-state" aria-label="Permalink to &quot;Phone Service State {#phone-service-state}&quot;">​</a></h3><p>Normalmente indica l&#39;ora dell&#39;ultima connessione. A volte mostra XXX Blu Con XXX, ma è una fase temporanea e cambierà in Last Connect HH:MM</p><h3 id="bluetooth-device-1" tabindex="-1">Bluetooth Device <a class="header-anchor" href="#bluetooth-device-1" aria-label="Permalink to &quot;Bluetooth Device {#bluetooth-device-1}&quot;">​</a></h3><p>Il Bluetooth dovrebbe essere sempre connesso.</p><h3 id="device-mac-address" tabindex="-1">Device Mac Address <a class="header-anchor" href="#device-mac-address" aria-label="Permalink to &quot;Device Mac Address {#device-mac-address}&quot;">​</a></h3><p>Dovrebbe essere una stringa di sei coppie di numeri esadecimali, unica per ogni sensore.</p><h3 id="bluetooth-pairing" tabindex="-1">Bluetooth Pairing <a class="header-anchor" href="#bluetooth-pairing" aria-label="Permalink to &quot;Bluetooth Pairing {#bluetooth-pairing}&quot;">​</a></h3><p>Dovrebbe restare &quot;Disabled, tap to enable&quot;. Fai attenzione a NON toccarlo.<br> Se lo tocchi per errore, toccalo di nuovo finché non torna disattivato.</p><h3 id="slowest-wake-up" tabindex="-1">Slowest wake up <a class="header-anchor" href="#slowest-wake-up" aria-label="Permalink to &quot;Slowest wake up {#slowest-wake-up}&quot;">​</a></h3><p>Puoi ignorarlo. xDrip non passa il tempo ad aspettare le letture: comincia ad aspettarle dopo un certo tempo (di solito 5 minuti). Se a quel punto non arrivano dati, vedrai &quot;Woke up early&quot;, che significa che xDrip si aspettava dati pronti ma non ce n&#39;erano. Slowest wake up è il ritardo più lungo registrato prima di ricevere normalmente i dati.</p><h3 id="next-wake-up" tabindex="-1">Next Wake up <a class="header-anchor" href="#next-wake-up" aria-label="Permalink to &quot;Next Wake up {#next-wake-up}&quot;">​</a></h3><p>Dovrebbe indicare 5 minuti</p><br><h1 id="event-logs" tabindex="-1">Log eventi <a class="header-anchor" href="#event-logs" aria-label="Permalink to &quot;Log eventi {#event-logs}&quot;">​</a></h1><p>Dal menu verticale ... in alto a destra nella schermata principale, seleziona Visualizza eventi Log</p><img src="'+t+'" style="zoom:40%;"><h3 id="libreoopalgorithm" tabindex="-1">LibreOOPAlgorithm <a class="header-anchor" href="#libreoopalgorithm" aria-label="Permalink to &quot;LibreOOPAlgorithm {#libreoopalgorithm}&quot;">​</a></h3><p>Dovresti vedere una serie di righe nel formato HH:MM Creating BG time = NNN raw = RRRR dove HH:MM è l&#39;ora, NNN è un contatore interno del tempo (una nuova lettura ha un numero più alto della precedente) e RRRR è il valore raw letto dal sensore, in decimi di mg/dl (1000 corrisponde a 100 mg/dl o 5,5 mmol/l). Questo indica che il sensore è connesso e che vengono ricevute letture valide. Dovrebbe esserci una lettura ogni minuto, anche se alcune possono mancare, come è successo qui.</p><br><h2 id="cannot-nfc-scan-new-sensor-nfc-timeout" tabindex="-1">Impossibile scansionare con NFC un nuovo sensore - Timeout NFC <a class="header-anchor" href="#cannot-nfc-scan-new-sensor-nfc-timeout" aria-label="Permalink to &quot;Impossibile scansionare con NFC un nuovo sensore - Timeout NFC {#cannot-nfc-scan-new-sensor-nfc-timeout}&quot;">​</a></h2><p>C&#39;è un problema emergente, soprattutto in Europa, per cui non è possibile avviare il sensore con una scansione NFC. Invece del messaggio &quot;Scansionato OK!&quot; dopo &quot;Scansione in corso&quot;, vedrai &quot;Timeout lettura NFC&quot; o &quot;Timeout diagnostico NFC&quot;. Guarda nei log di debug. Se vedi il messaggio &quot;Sensor type unknown, returning libre1 as failsafe&quot; oppure &quot;Libre sensor of type Libre1 detected&quot;, devi aggiornare sia OOP2 sia xDrip.</p><img src="'+i+'" style="zoom:40%;"><p>Devi scaricare una versione di OOP2 della fine di maggio 2023 e anche aggiornare xDrip-plus a una versione del 2023-05-27 o successiva. Una nuova versione dei sensori, &quot;C5&quot; con firmware aggiornato, richiede queste versioni aggiornate.</p><h2 id="losing-bluetooth-connection-with-samsung-phone" tabindex="-1">Perdi la connessione Bluetooth con un telefono Samsung? <a class="header-anchor" href="#losing-bluetooth-connection-with-samsung-phone" aria-label="Permalink to &quot;Perdi la connessione Bluetooth con un telefono Samsung? {#losing-bluetooth-connection-with-samsung-phone}&quot;">​</a></h2><p>Diverse persone con un telefono Samsung hanno segnalato di perdere a volte la connessione con il sensore. Se capita anche a te, puoi provare a cambiare alcune impostazioni Bluetooth. Fai clic sul codice QR e poi scansionalo come indicato.</p><p><a href="./libre2direct-qr-samsung.html"><img src="'+r+'" style="zoom:50%;"></a></p><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.05.26" target="_blank" rel="noreferrer"><em>Ultima modifica 4/6/2023</em></a></p>',55)])])}const P=n(u,[["render",d]]);export{q as __pageData,P as default};
